  ('DAC-R-90010', '2026-09-01', '4 Pneus 11R22.5 pour le véhicule de l’abattoir AA 565 GA', 'pneumatiques', 940000, null, 'SICAS', 'SICAS', 'AA565GA', 'DA200-2609011', null, 'Chargée le 14 septembre 2026 depuis le registre des demandes d''achat du parc (SUIVI_PARC). Registre des demandes d''achat du parc, type « DA » : HT 940000, TVA 169200, TTC 1109200.'),
  ('DAC-R-90011', '2026-09-01', 'ENTRETIEN ENZIN AFFECTE A KARAOUNI 1 AUX 500 HEURES', 'maintenance-preventive', 215000, null, 'MECANORIDIAL', 'MECANO RIDIAL', null, 'DA200-2609014', null, 'Chargée le 14 septembre 2026 depuis le registre des demandes d''achat du parc (SUIVI_PARC). Registre des demandes d''achat du parc, type « DA » : HT 215000, TVA —, TTC 215000. MECANO RIDIAL n''a pas de fiche au référentiel des prestataires : le fournisseur reste en clair.'),
  ('DAC-R-90012', '2026-09-03', '8 Pneus 215/60R17 (4 pour AA 189 JM et 4 pneus AA 550 JD)', 'pneumatiques', 676000, null, 'SSPI', 'SSPI', 'AA189JM', 'DA200-2609032', null, 'Chargée le 14 septembre 2026 depuis le registre des demandes d''achat du parc (SUIVI_PARC). Registre des demandes d''achat du parc, type « DA » : HT 676000, TVA 121680, TTC 797680. SSPI n''a pas de fiche au référentiel des prestataires : le fournisseur reste en clair.'),
