  ('DAC-R-90016', '2026-09-04', 'TRANSPORT PERSONNEL GOROM2 A POUSSINIERE NOTTO', 'divers', 120000, 'PRE-2026-00030', 'DAMENDOYE', 'DAME NDOYE', null, 'CA200-2609059', null, 'Chargée le 14 septembre 2026 depuis le registre des demandes d''achat du parc (SUIVI_PARC). Registre des demandes d''achat du parc, type « PIECES » : HT 120000, TVA —, TTC 120000.'),
  ('DAC-R-90017', '2026-09-04', 'ENTRETIEN AA 963 JM AUX 55000 KMS A LASA', 'maintenance-preventive', 47154, null, 'LASA', 'LASA', 'AA963JM', 'DA200-2609042', null, 'Chargée le 14 septembre 2026 depuis le registre des demandes d''achat du parc (SUIVI_PARC). Registre des demandes d''achat du parc, type « DA » : HT 47154, TVA 8488, TTC 55642. LASA n''a pas de fiche au référentiel des prestataires : le fournisseur reste en clair.'),
  ('DAC-R-90018', '2026-09-04', 'LOCATION PERSONNEL TRANSPORT AGENTS MAINTENANCES DANS LES FERMES', 'maintenance-curative', 842096, null, 'MBAGNICKGAYE', 'MBAGNICK GAYE', null, 'DA200-2609043', null, 'Chargée le 14 septembre 2026 depuis le registre des demandes d''achat du parc (SUIVI_PARC). Registre des demandes d''achat du parc, type « DA » : HT 842096, TVA 42105, TTC 799991.'),
  ('DAC-R-90019', '2026-09-04', 'DIAGNOSTIC ET REPARATION CAPTEUR, SYSTEME AD BLUE, VEHICULE MR DIONGUE AA 716 FK PAR', 'maintenance-curative', 303500, null, 'BABAMECANO', 'BABA MECANO', 'AA716FK', 'DA200-2609044', null, 'Chargée le 14 septembre 2026 depuis le registre des demandes d''achat du parc (SUIVI_PARC). Registre des demandes d''achat du parc, type « DA » : HT 303500, TVA —, TTC 303500. BABA MECANO n''a pas de fiche au référentiel des prestataires : le fournisseur reste en clair.'),
