  ('DAC-R-90021', '2026-09-01', 'LOCATION CAMION POUR LIVRAISON POUSSINS PAR', 'divers', 336000, null, 'DRIBRAHIMAWADE', 'DR IBRAHIMA WADE', null, 'DA200-2609046', null, 'Chargée le 14 septembre 2026 depuis le registre des demandes d''achat du parc (SUIVI_PARC). Le registre ne date pas cette demande : son numéro en donne le mois, le jour reste inconnu. Registre des demandes d''achat du parc, type « DA » : HT 336000, TVA 16800, TTC 319200.'),
  ('DAC-R-90022', '2026-09-01', 'ENTRETIEN ET MAINTENANCE DES VEHICULES DE LIVRAISON DE MARQUE TATA', 'maintenance-preventive', 10151519, null, 'TATAINTERNATIONAL', 'TATA INTERNATIONAL', null, 'DA200-2609050', null, 'Chargée le 14 septembre 2026 depuis le registre des demandes d''achat du parc (SUIVI_PARC). Le registre ne date pas cette demande : son numéro en donne le mois, le jour reste inconnu. Registre des demandes d''achat du parc, type « DA » : HT 10151519, TVA 1827273, TTC 11978792. TATA INTERNATIONAL n''a pas de fiche au référentiel des prestataires : le fournisseur reste en clair.')
  ) as v(numero, date, objet, poste, ht, prestataire_numero, cle_fournisseur, fournisseur, immatriculation, numero_da, document, commentaire)
  left join prestataire pn on pn.numero = v.prestataire_numero
  left join lateral (select x.id from prestataire x where v.cle_fournisseur is not null and upper(regexp_replace(x.raison_sociale, '[^A-Za-z0-9]', '', 'g')) = v.cle_fournisseur order by x.numero limit 1) pc on true
  left join vehicule ve on ve.immatriculation = v.immatriculation
on conflict (numero) do nothing;
